def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Find uniform, contiguous non-background runs on each outer edge.
    def edge_runs(side):
        if side in ("top", "bottom"):
            r = 0 if side == "top" else h - 1
            vals = grid[r]
        else:
            c = 0 if side == "left" else w - 1
            vals = [grid[r][c] for r in range(h)]

        runs = []
        i = 0
        while i < len(vals):
            if vals[i] == bg:
                i += 1
                continue
            j = i + 1
            while j < len(vals) and vals[j] == vals[i]:
                j += 1
            runs.append((side, i, j, vals[i]))
            i = j
        return runs

    pairs = []
    for a, b in (("top", "bottom"), ("left", "right")):
        for ra in edge_runs(a):
            for rb in edge_runs(b):
                if ra[3] == rb[3] and ra[2] - ra[1] == rb[2] - rb[1]:
                    pairs.append((ra, rb))

    if not pairs:
        return [row[:] for row in grid]

    bar_color = pairs[0][0][3]
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] != bar_color]
    if not markers:
        return [row[:] for row in grid]

    # Select the bar run whose span contains the marker coordinates; its
    # relative positions determine which rays are active on both bars.
    def contained(run, marker):
        side, start, end, _ = run
        pos = marker[1] if side in ("top", "bottom") else marker[0]
        return start <= pos < end

    pair = max(pairs, key=lambda p: sum(
        contained(run, m) for run in p for m in markers
    ))
    run = max(pair, key=lambda x: sum(contained(x, m) for m in markers))
    offsets = sorted({
        (m[1] if run[0] in ("top", "bottom") else m[0]) - run[1]
        for m in markers if contained(run, m)
    })
    if not offsets:
        return [row[:] for row in grid]

    paint = markers[0][2]
    out = [row[:] for row in grid]

    for side, start, end, _ in pair:
        for off in offsets:
            pos = start + off
            if side == "top":
                r, c, dr, dc = 1, pos, 1, 0
            elif side == "bottom":
                r, c, dr, dc = h - 2, pos, -1, 0
            elif side == "left":
                r, c, dr, dc = pos, 1, 0, 1
            else:
                r, c, dr, dc = pos, w - 2, 0, -1

            while 0 <= r < h and 0 <= c < w:
                if grid[r][c] == paint:
                    out[r][c] = 4
                    break
                out[r][c] = paint
                r += dr
                c += dc

    return out
